/** Writes supabase/seed.sql from lib/taxonomy.ts and lib/gamification.ts. Run: npm run gen:seed */
import { writeFileSync } from "fs";
import { TOPICS } from "../lib/taxonomy";
import { BADGES } from "../lib/gamification";
import { LOCAL_SOURCES } from "../ingest/legistar.config";

const q = (s: string | null | undefined) => (s == null ? "null" : `'${s.replace(/'/g, "''")}'`);

const lines = [
  "-- GENERATED by scripts/gen-seed.ts — do not edit by hand.",
  "",
  "insert into topics (slug, name, parent_slug) values",
  // parents first so the FK is satisfied
  [...TOPICS].sort((a, b) => Number(!!a.parent) - Number(!!b.parent))
    .map((t) => `  (${q(t.slug)}, ${q(t.name)}, ${q(t.parent)})`).join(",\n") +
    "\non conflict (slug) do update set name = excluded.name, parent_slug = excluded.parent_slug;",
  "",
  "insert into badges (slug, name, description, icon) values",
  BADGES.map((b) => `  (${q(b.slug)}, ${q(b.name)}, ${q(b.description)}, ${q(b.icon)})`).join(",\n") +
    "\non conflict (slug) do update set name = excluded.name, description = excluded.description, icon = excluded.icon;",
  "",
  "insert into jurisdictions (id, level, name, state) values",
  "  ('ocd-division/country:us', 'federal', 'United States', null)" +
    LOCAL_SOURCES.map((s) => `,\n  (${q(s.jurisdictionId)}, 'city', ${q(s.name)}, ${q(s.state)})`).join("") +
    "\non conflict (id) do nothing;",
  "",
  ...(LOCAL_SOURCES.length
    ? [
        "insert into local_sources (id, jurisdiction_id, name) values",
        LOCAL_SOURCES.map((s) => `  (${q(s.client)}, ${q(s.jurisdictionId)}, ${q(s.name)})`).join(",\n") +
          "\non conflict (id) do nothing;",
      ]
    : []),
  "",
];

writeFileSync("supabase/seed.sql", lines.join("\n"));
console.log(`seed.sql: ${TOPICS.length} topics, ${BADGES.length} badges, ${LOCAL_SOURCES.length} local sources`);
